// ── STEP 0: 名前・アイコン ──if (step===0) return (<div style={setup}><div style={{textAlign:“center”,marginBottom:“28px”}}><div style={{fontSize:“32px”,fontWeight:“700”,letterSpacing:“2px”,marginBottom:“4px”}}>かくたび</div><div style={{fontSize:“13px”,color:”#999”}}>書くを習慣化するアプリ</div></div><Steps current={0} total={4}/><div style={{fontSize:“22px”,fontWeight:“700”,marginBottom:“6px”}}>はじめまして</div><div style={{fontSize:“13px”,color:”#999”,marginBottom:“28px”}}>お名前とアイコンを設定してください</div><div style={{textAlign:“center”,marginBottom:“24px”}}><div onClick={()=>setShowAvatarPicker(!showAvatarPicker)} style={{width:“76px”,height:“76px”,borderRadius:“50%”,border:“2px dashed #e0e0e0”,display:“flex”,alignItems:“center”,justifyContent:“center”,cursor:“pointer”,margin:“0 auto”,background:”#fafafa”,position:“relative”}}><UserAvatarComp size={76}/><div style={{position:“absolute”,bottom:0,right:0,width:“22px”,height:“22px”,background:”#111”,borderRadius:“50%”,display:“flex”,alignItems:“center”,justifyContent:“center”,fontSize:“11px”,color:“white”}}> </div></div><div style={{fontSize:“11px”,color:”#bbb”,marginTop:“8px”}}>タップして変更</div></div>{showAvatarPicker&&(<div style={{background:”#fafafa”,borderRadius:“12px”,padding:“16px”,marginBottom:“16px”}}><div style={{display:“grid”,gridTemplateColumns:“repeat(6,1fr)”,gap:“6px”,maxHeight:“200px”,overflowY:“auto”}}>{AVATAR_EMOJIS.map(a=><button key={a} onClick={()=>{setUserAvatar(a);setShowAvatarPicker(false);}} style={{fontSize:“22px”,padding:“6px”,border:userAvatar===a?“2px solid #111”:“2px solid transparent”,borderRadius:“8px”,background:“white”,cursor:“pointer”}}>{a}</button>)}</div></div>)}<input value={nameInput} onChange={e=>setNameInput(e.target.value)} placeholder=“例：やまぐち” style={{padding:“14px 16px”,border:“1px solid #e0e0e0”,borderRadius:“10px”,fontSize:“16px”,outline:“none”,fontFamily:“inherit”,marginBottom:“8px”}} onFocus={e=>e.target.style.border=“1px solid #111”} onBlur={e=>e.target.style.border=“1px solid #e0e0e0”}/><div style={{fontSize:“11px”,color:”#bbb”,marginBottom:“auto”}}>コミュニティで表示される名前です</div><button onClick={()=>{if(nameInput.trim()){setUserName(nameInput.trim());setStep(1);}}} style={{marginTop:“32px”,padding:“14px”,background:nameInput.trim()?”#111”:”#f0f0f0”,border:“none”,borderRadius:“10px”,color:nameInput.trim()?”#fff”:”#bbb”,fontSize:“15px”,fontWeight:“600”,cursor:nameInput.trim()?“pointer”:“not-allowed”,fontFamily:“inherit”}}>つぎへ →</button></div>);
